const rtdal004676Source0003 = `methods::setGeneric("add_auto_targets",
  signature = methods::signature("x", "method"),
  function(x, method) {
    assert_required(x)
    assert_required(method)
    assert(
      is_conservation_problem(x)
    )
    assert(
      is_inherits(
        method,
        c("character", "TargetMethod", "list")
      ),
      msg = paste(
        "{.arg method} must be a {.cls character} value,",
        "{.cls character} vector, {.cls list}, or object specifying",
        "a target method."
      )
    )
    standardGeneric("add_auto_targets")
  }
)`

const rtdal004676Source0004 = `methods::setMethod("add_auto_targets",
  methods::signature("ConservationProblem", "character"),
  function(x, method) {
    # assert valid arguments
    assert(
      assertthat::is.string(method),
      assertthat::noNA(method)
    )
    # verify that method has a valid value
    ## note this will throw an error if method is not valid
    m <- get_target_method(method)
    assert(inherits(m, "TargetMethod"), .internal = TRUE)
    # add method
    add_auto_targets(x, m)
  }
)`

const rtdal004676Source0005 = `methods::setMethod("add_auto_targets",
  methods::signature("ConservationProblem", "list"),
  function(x, method) {
    # assert arguments are valid
    assert(
      is_conservation_problem(x),
      is.list(method)
    )
    assert(
      isTRUE(length(method) == x$number_of_features()),
      msg = c(
        "!" =
          "{.arg method} must specify a method for each feature in {.arg x}.",
        "x" = "{.arg x} has {.val {x$number_of_features()}} features.",
        "x" = "{.arg method} has {.val {length(method)}} elements."
      )
    )
    # add targets
    internal_add_auto_targets.list(x, method)
  }
)`

const rtdal004676Source0006 = "internal_add_auto_targets.list <- function(x, method, call = fn_caller_env()) {\n  # assert valid arguments\n  assert(\n    is_conservation_problem(x),\n    is.list(method),\n    call = call,\n    .internal = TRUE\n  )\n  assert(\n    all_elements_inherit(method, c(\"character\", \"TargetMethod\")),\n    msg = c(\n      \"!\" = paste(\n        \"All {.arg ...} arguments must contain a\",\n        \"{.cls character} value or object specifying\",\n        \"a target setting method.\"\n      )\n    ),\n    call = call\n  )\n\n  # if method contains any characters, then override with specified method\n  method <- lapply(method, function(x) {\n    if (is.character(x)) {\n      return(get_target_method(x, call = call))\n    }\n    x\n  })\n\n  # create data frame with targets\n  targets <- tibble::tibble(\n    feature = x$feature_names(),\n    target = vapply(\n      seq_len(x$number_of_features()),\n      FUN.VALUE = numeric(1),\n      function(i) {\n        method[[i]]$calculate_targets(x = x, features = i, call = call)\n      }\n    ),\n    type = vapply(method, FUN.VALUE = character(1), `[[`, \"type\")\n  )\n\n  # determine target names\n  target_name <- unique(vapply(method, FUN.VALUE = character(1), `[[`, \"name\"))\n  if (length(target_name) > 1) {\n    target_name <- \"Multiple target methods\"\n  }\n\n  # add targets to problem\n  x$add_targets(\n    R6::R6Class(\n      \"AutoTargets\",\n      inherit = Target,\n      public = list(\n        name = target_name,\n        data = list(targets = targets, type = method$type),\n        repr = function(compact = TRUE) {\n          d <- self$get_data(\"targets\")\n          type <- unique(d$type)\n          if (identical(length(type), 1L)) {\n            out <- cli::format_inline(\n              \"{self$name} ({type} values between \",\n              \"{repr.numeric(range(d$target))})\"\n            )\n          } else {\n            out <- cli::format_inline(\n              \"{self$name} (mixed values between \",\n              \"{repr.numeric(range(d$target))})\"\n            )\n          }\n          out\n        },\n        output = function(x) {\n          # assert x is a conservation problem\n          assert(\n            is_conservation_problem(x),\n            .internal = TRUE\n          )\n          # return targets for optimization\n          target_optimization_format(x, self$get_data(\"targets\"))\n        }\n      )\n    )$new()\n  )\n}"

const rtdal004676Source0007 = `methods::setMethod("add_auto_targets",
  methods::signature("ConservationProblem", "TargetMethod"),
  function(x, method) {
    # assert arguments are valid
    assert(
      is_conservation_problem(x),
      inherits(method, "TargetMethod")
    )
    # add targets
    internal_add_auto_targets.TargetMethod(x, method)
  }
)`

const rtdal004676Source0008 = `internal_add_auto_targets.TargetMethod <- function(x, method,
                                                   call = fn_caller_env()) {
  # assert valid arguments
  assert(
    is_conservation_problem(x),
    inherits(method, "TargetMethod"),
    call = call,
    .internal = TRUE
  )

  # create data frame with targets
  targets <- tibble::tibble(
    feature = x$feature_names(),
    target = method$calculate_targets(
      x = x,
      features = seq_len(x$number_of_features()),
      call = call
    ),
    type = method$type
  )

  # add targets to problem
  x$add_targets(
    R6::R6Class(
      "AutoTargets",
      inherit = Target,
      public = list(
        name = method$name,
        data = list(targets = targets),
        repr = function(compact = TRUE) {
          d <- self$get_data("targets")
          type <- d$type[[1]]
          if (identical(length(unique(d$target)), 1L)) {
            out <- cli::format_inline(
              "{self$name} ({type} values all equal to ",
              "{repr.numeric(d$target[[1]])})"
            )
          } else {
            out <- cli::format_inline(
              "{self$name} ({type} values between ",
              "{repr.numeric(range(d$target))})"
            )
          }
          out
        },
        output = function(x) {
          # assert x is a conservation problem
          assert(
            is_conservation_problem(x),
            .internal = TRUE
          )
          # return targets for optimization
          target_optimization_format(x, self$get_data("targets"))
        }
      )
    )$new()
  )
}`

