const rtdal004677Source0003 = `add_binary_decisions <- function(x) {
  # assert argument is valid
  assert_required(x)
  assert(is_conservation_problem(x))
  # add decision
  x$add_decisions(
    R6::R6Class(
      "BinaryDecision",
      inherit = Decision,
      public = list(
        name = "binary decision",
        apply = function(x) {
          assert(inherits(x,"OptimizationProblem"), .internal = TRUE)
          invisible(rcpp_apply_decisions(x$ptr, "B", 0, 1))
        }
      )
    )$new()
  )
}`

