const rtdal004687Source0003 = `add_extra_portfolio <- function(x) {
  # assert that arguments are valid
  assert_required(x)
  assert(is_conservation_problem(x))
  # assert dependencies available
  assert(is_installed("gurobi"))
  assert(
    utils::packageVersion("gurobi") >= as.package_version("8.0.0"),
    msg = paste(
      "This portfolio requires version 8.0.0 (or greater) of the",
      "Gurobi software."
    )
  )
  # add portfolio
  x$add_portfolio(
    R6::R6Class(
      "ExtraPortfolio",
      inherit = Portfolio,
      public = list(
        name = "extra portfolio",
        run = function(x, solver) {
          ## check that problem has gurobi solver
          assert(
            inherits(solver, "GurobiSolver"),
            call = rlang::expr(add_gap_portfolio()),
            msg = "The solver must be specified using {.fn add_gurobi_solver}."
          )
          ## solve problem
          sol <- solver$solve(x, PoolSearchMode = 1)
          ## compile results
          if (!is.null(sol$pool)) {
            sol <- append(
              list(sol[-which(names(sol) == "pool")]),
              lapply(
                sol$pool,
                function(z) list(
                  x = z$xn,
                  objective = z$objective,
                  status = z$status,
                  runtime = sol$runtime,
                  gap = z$gap,
                  objbound = z$objbound
                )
              )
            )
          } else {
           sol <- list(sol)
          }
          ## return solution
          return(sol)
        }
      )
    )$new()
  )
}`

