const rtdal004697Source0008 = `methods::setMethod("add_locked_out_constraints",
  methods::signature("ConservationProblem", "sf"),
  function(x, locked_out) {
    # assert valid arguments
    assert(
      is_conservation_problem(x),
      inherits(locked_out, "sf"),
      x$number_of_zones() == 1
    )
    assert(
      is_same_crs(x$data$cost, locked_out),
      msg = paste(
        "{.arg locked_out} and planning units for {.arg x}",
        "must have the same coordinate reference system."
      )
    )
    assert(
      is_spatial_extents_overlap(x$data$cost, locked_out),
      msg = paste(
        "{.arg locked_out} and planning units for {.arg x}",
        "must have overlapping spatial extents."
      )
    )
    # add constraints using indices
    internal_add_manual_locked_constraints(
      x,
      tibble::tibble(
        idx = intersecting_units(x$data$cost, locked_out),
        zone = x$zone_names(),
        status = 0
      ),
      lb = FALSE,
      ub = TRUE
    )
  }
)`

