const rtdal004703Source0003 = `add_max_cover_objective <- function(x, budget) {
  # assert argument is valid
  assert_required(x)
  assert_required(budget)
  assert(
    is_conservation_problem(x),
    is.numeric(budget),
    all_finite(budget),
    all_positive(budget),
    is_budget_length(x, budget)
  )
  # add objective to problem
  x$add_objective(
    R6::R6Class(
      "MaximumCoverageObjective",
      inherit = Objective,
      public = list(
        name = "maximum coverage objective",
        has_weights = TRUE,
        has_targets = FALSE,
        data = list(budget = budget),
        apply = function(x, y, weights) {
          assert(
            inherits(x, "OptimizationProblem"),
            inherits(y, "ConservationProblem"),
            is.numeric(weights),
            .internal = TRUE
          )
          invisible(
            rcpp_apply_max_cover_objective(
              x$ptr,
              y$planning_unit_costs(),
              self$get_data("budget"),
              weights
            )
          )
        }
      )
    )$new()
  )
}`

