const rtdal004722Source0001 = `as_km2 <- function(x, unit) {
  # assert arguments are valid
  assert(
    is.numeric(x),
    is.character(unit),
    .internal = TRUE
  )
  # main calculations
  if (
    identical(length(unit), 1L) ||
    identical(length(unique(unit)), 1L)
  ) {
    out <- as.numeric(
      units::set_units(
        units::set_units(x, unit[[1]], mode = "standard"),
        "km^2"
      )
    )
  } else {
    out <- vapply(
      seq_along(x),
      FUN.VALUE = numeric(1),
      function(i) {
        as.numeric(
          units::set_units(
            units::set_units(x[[i]], unit[[i]], mode = "standard"),
            "km^2",
            mode = "standard"
          )
        )
      }
    )
  }
  # return result
  out
}`

