const rtdal004735Source0010 = `get_sim_zones_pu_raster <- function() {
  x <- terra::rast(
    system.file("extdata", "sim_zones_pu_raster.tif", package = "prioritizr")
  )
  terra::crs(x) <- na_crs
  terra::ext(x) <- c(0, 1, 0, 1)
  names(x) <- paste0("zone_", seq_len(terra::nlyr(x)))
  x
}`

