const rtdal004778Source0002 = `methods::setGeneric(
  "planning_unit_solution_format",
  signature = methods::signature("x", "status", "data"),
  function(x, status, data, ...) {
    assert_required(x)
    assert_required(status)
    assert(
      is_conservation_problem(x),
      is_inherits(status, c("matrix", "list"))
    )
    if (is.list(status)) {
      assert(all_elements_inherit(status, "matrix"))
    }
    standardGeneric("planning_unit_solution_format")
  }
)`

const rtdal004778Source0003 = `methods::setMethod(
  "planning_unit_solution_format",
  methods::signature("ConservationProblem", "matrix", "missing"),
  function(
    x, status, data, prefix = NULL, append = FALSE, call = fn_caller_env()
  ) {
    planning_unit_solution_format(
      x, status, data = x$data$cost,
      prefix = prefix, append = append, call = call
    )
  }
)`

const rtdal004778Source0004 = "methods::setMethod(\n  \"planning_unit_solution_format\",\n  methods::signature(\"ConservationProblem\", \"list\", \"missing\"),\n  function(\n    x, status, data, prefix = NULL, append = FALSE, call = fn_caller_env()\n  ) {\n    # create a prefix for each element of status\n    if (is.null(prefix)) {\n      prefix <- list(NULL)[rep(1, length(status))]\n    }\n    if (length(prefix) == 1) {\n      prefix <- list(prefix)[rep(1, length(status))]\n    }\n    # assert prefix specified for each status\n    assert(\n      identical(length(prefix), length(status)),\n      call = call,\n      .internal = TRUE,\n      msg = paste0(\n        \"{.arg prefix} should contain a single `character` value or a \",\n        \"value for each element of status.\"\n      )\n    )\n    # process data\n    if (inherits(x$data$cost, c(\"sf\", \"Spatial\", \"data.frame\"))) {\n      ### if sf/Spatial/data.frame, then process separately in matrix format to\n      ### reduce memory requirements\n      out <- lapply(seq_along(status), function(i) {\n        planning_unit_solution_format(\n          x, status[[i]], data = data.frame(1),\n          prefix = prefix[[i]], append = FALSE, call = call\n        )\n      })\n      ### cbind the columns together\n      out <- do.call(cbind, out)\n      ### if append, then add in additional columns from the planning unit\n      ### dataset\n      if (isTRUE(append)) {\n        if (inherits(x$data$cost, \"sf\")) {\n          out <- cbind(sf::st_drop_geometry(x$data$cost), out)\n        } else if (inherits(x$data$cost, \"Spatial\")) {\n          out <- cbind(x$data$cost@data, out)\n        } else if (inherits(x$data$cost, \"data.frame\")) {\n          out <- cbind(x$data$cost, out)\n        }\n      }\n      ### perform additional processing needed for sf/Spatial datasets\n      if (inherits(x$data$cost, \"sf\")) {\n        out <- tibble::as_tibble(out)\n        out$geometry <- sf::st_geometry(x$data$cost)\n        out <- sf::st_sf(out, crs = sf::st_crs(x$data$cost))\n      } else if (inherits(x$data$cost, \"Spatial\")) {\n        d <- out\n        rownames(d) <- rownames(x$data$cost)\n        out <- x$data$cost\n        out@data <- d\n      } else {\n        out <- tibble::as_tibble(out)\n      }\n    } else {\n      ### otherwise, then process separately in planning unit data format\n      out <- lapply(seq_along(status), function(i) {\n        planning_unit_solution_format(\n          x, status[[i]], append = append, call = call\n        )\n      })\n      ### set names\n      names(out) <- prefix\n    }\n    # return result\n    out\n  }\n)"

const rtdal004778Source0005 = `methods::setMethod(
  "planning_unit_solution_format",
  methods::signature("ConservationProblem", "matrix", "numeric"),
  function(
    x, status, data, prefix = NULL, append = FALSE, call = fn_caller_env()
  ) {
    # assert valid arguments
    assert(
      identical(ncol(status), x$number_of_zones()),
      identical(nrow(status), x$number_of_planning_units()),
      .internal = TRUE
    )
    # initialize matrices
    out <- c(NA_real_, x$number_of_total_units())
    # prepare output
    out[x$planning_unit_indices()] <- status
    # return output
    out
})`

const rtdal004778Source0006 = `methods::setMethod(
  "planning_unit_solution_format",
  methods::signature("ConservationProblem", "matrix", "matrix"),
  function(
    x, status, data, prefix = NULL, append = FALSE, call = fn_caller_env()
  ) {
    # assert valid arguments
    assert(
      identical(ncol(status), x$number_of_zones()),
      identical(nrow(status), x$number_of_planning_units()),
      .internal = TRUE
    )
    # initialize matrices
    out <- matrix(
      NA_real_,
      nrow = x$number_of_total_units(),
      ncol = x$number_of_zones()
    )
    # assign status values
    out[x$planning_unit_indices(), ] <- status
    # assign names
    if (is.null(prefix)) {missing
      colnames(out) <- x$zone_names()
    } else if (identical(ncol(out), 1L)) {
      colnames(out) <- prefix
    } else {
      colnames(out) <- paste0(prefix, "_", x$zone_names())
    }
    # return output
    out
})`

const rtdal004778Source0007 = `methods::setMethod(
  "planning_unit_solution_format",
  methods::signature("ConservationProblem", "matrix", "data.frame"),
  function(
    x, status, data, prefix = NULL, append = FALSE, call = fn_caller_env()
  ) {
    # assert valid arguments
    assert(
      identical(
        length(status),
        x$number_of_planning_units() * x$number_of_zones()
      ),
      .internal = TRUE,
      msg = c(
        paste0(
          "{.arg status} must have ",
          x$number_of_planning_units() * x$number_of_zones(),
          " elements."
        ),
        "x" = "{.arg status} has {length(status)} element{?s}."
      )
    )
    # prepare data in matrix format
    out <- planning_unit_solution_format(
      x, status, matrix(1), prefix = prefix, append = append, call = call
    )
    # if needed, append columns from the planning unit dataset
    out <- as.data.frame(out)
    if (isTRUE(append)) {
      out <- cbind(x$data$cost, out)
    }
    # return result
    tibble::as_tibble(out)
})`

const rtdal004778Source0008 = `methods::setMethod(
  "planning_unit_solution_format",
  methods::signature("ConservationProblem", "matrix", "Spatial"),
  function(
    x, status, data, prefix = NULL, append = FALSE, call = fn_caller_env()
  ) {
    # assert valid arguments
    assert(
      identical(
        length(status),
        x$number_of_planning_units() * x$number_of_zones()
      ),
      .internal = TRUE,
      msg = c(
        paste0(
          "{.arg status} must have ",
          x$number_of_planning_units() * x$number_of_zones(),
          " elements."
        ),
        "x" = "{.arg status} has {length(status)} element{?s}."
      )
    )
    # extract data
    data <- x$data$cost
    # prepare data in matrix format
    out <- planning_unit_solution_format(
      x, status, matrix(1), prefix = prefix, append = append, call = call
    )
    # if needed, append columns from the planning unit dataset
    out <- as.data.frame(out)
    if (isTRUE(append)) {
      out <- cbind(data@data, out)
    }
    # return result
    rownames(out) <- rownames(data@data)
    data@data <- out
    data
})`

const rtdal004778Source0009 = `methods::setMethod(
  "planning_unit_solution_format",
  methods::signature("ConservationProblem", "matrix", "sf"),
  function(
    x, status, data, prefix = NULL, append = FALSE, call = fn_caller_env()
  ) {
    # assert valid arguments
    assert(
      identical(
        length(status),
        x$number_of_planning_units() * x$number_of_zones()
      ),
      .internal = TRUE,
      msg = c(
        paste0(
          "{.arg status} must have ",
          x$number_of_planning_units() * x$number_of_zones(),
          " elements."
        ),
        "x" = "{.arg status} has {length(status)} element{?s}."
      )
    )
    # prepare data in matrix format
    out <- planning_unit_solution_format(
      x, status, matrix(1), prefix = prefix, append = append, call = call
    )
    # if needed, append columns from the planning unit dataset
    out <- as.data.frame(out)
    if (isTRUE(append)) {
      out <- cbind(sf::st_drop_geometry(x$data$cost), out)
    }
    # convert to sf
    out <- tibble::as_tibble(out)
    out$geometry <- sf::st_geometry(x$data$cost)
    sf::st_sf(out, crs = sf::st_crs(x$data$cost))
})`

const rtdal004778Source0010 = `methods::setMethod(
  "planning_unit_solution_format",
  methods::signature("ConservationProblem", "matrix", "Raster"),
  function(
    x, status, data, prefix = NULL, append = FALSE, call = fn_caller_env()
  ) {
    # assert valid arguments
    assert(
      identical(
        length(status),
        x$number_of_planning_units() * x$number_of_zones()
      ),
      .internal = TRUE,
      msg = c(
        paste0(
          "{.arg status} must have ",
          x$number_of_planning_units() * x$number_of_zones(),
          " elements."
        ),
        "x" = "{.arg status} has {length(status)} element{?s}."
      )
    )
    # extract data
    idx <- x$planning_unit_indices()
    data <- x$data$cost
    # prepare output
    out <- data
    for (i in seq_len(raster::nlayers(out))) {
      out[[i]][idx] <- status[, i]
    }
    if (is.null(prefix)) {
      names(out) <- x$zone_names()
    } else if (isTRUE(raster::nlayers(out) == 1L)) {
      names(out) <- prefix
    } else {
      names(out) <- paste0(prefix, "_", x$zone_names())
    }
    # return result
    out
})`

const rtdal004778Source0011 = `methods::setMethod(
  "planning_unit_solution_format",
  methods::signature("ConservationProblem", "matrix", "SpatRaster"),
  function(
    x, status, data, prefix = NULL, append = FALSE, call = fn_caller_env()
  ) {
    # assert valid arguments
    assert(
      identical(
        length(status),
        x$number_of_planning_units() * x$number_of_zones()
      ),
      .internal = TRUE,
      msg = c(
        paste0(
          "{.arg status} must have ",
          x$number_of_planning_units() * x$number_of_zones(),
          " elements."
        ),
        "x" = "{.arg status} has {length(status)} element{?s}."
      )
    )
    # extract data
    idx <- x$planning_unit_indices()
    # prepare result
    out <- terra::rast(x$data$cost)
    for (i in seq_len(ncol(status))) {
      out[[i]][idx] <- status[, i]
    }
    if (is.null(prefix)) {
      names(out) <- x$zone_names()
    } else if (isTRUE(terra::nlyr(out) == 1)) {
      names(out) <- prefix
    } else {
      names(out) <- paste0(prefix, "_", x$zone_names())
    }
    # return result
    out
})`

