const rtdal004784Source0002 = `methods::setMethod(
  "problem",
  methods::signature(x = "Raster", features = "Raster"),
  function(x, features, run_checks = TRUE, ...) {
    assert(
      inherits(x, "Raster"),
      raster::nlayers(x) == 1
    )
    assert_dots_empty()
    problem(
      x,
      suppressWarnings(
        zones(features, zone_names = names(x), feature_names = names(features))
      ),
      run_checks = run_checks,
      ...
    )
  }
)`

const rtdal004784Source0003 = "methods::setMethod(\n  \"problem\",\n  methods::signature(x = \"Raster\", features = \"ZonesRaster\"),\n  function(x, features, run_checks = TRUE, ...) {\n    cli_warning(raster_pkg_deprecation_notice)\n    # assert that arguments are valid\n    assert(\n      inherits(x, \"Raster\"),\n      inherits(features, \"ZonesRaster\"),\n      assertthat::is.flag(run_checks),\n      raster::nlayers(x) > 0,\n      number_of_features(features) > 0,\n      raster::nlayers(x) == number_of_zones(features),\n      is_comparable_raster(x, features)\n    )\n    assert_dots_empty()\n    if (run_checks) {\n      assert(any_nonNA(x))\n      verify(all_positive(x))\n      verify(any_nonzero(x))\n      verify(all_positive(features))\n      verify(any_nonzero(features))\n      verify(any_nonNA(features))\n    }\n    # convert x to RasterLayer if has only one layer\n    if (\n      inherits(x, c(\"RasterStack\", \"RasterBrick\")) &&\n      raster::nlayers(x) == 1\n    ) {\n      x <- x[[1]]\n    }\n    # create rij matrix\n    idx <- planning_unit_indices(x)\n    rij <- suppressWarnings(\n      lapply(\n        as.list(features),\n        function(f) {\n          rij_matrix(x, `names<-`(f, feature_names(features)), idx = idx)\n        }\n      )\n    )\n    names(rij) <- zone_names(features)\n    # calculate feature abundances in total units\n    fatu <- vapply(\n      features, raster::cellStats, numeric(number_of_features(features)), \"sum\"\n    )\n    if (!is.matrix(fatu)) {\n      fatu <- matrix(\n        fatu, ncol = number_of_zones(features),\n        nrow = number_of_features(features)\n      )\n    }\n    colnames(fatu) <- zone_names(features)\n    rownames(fatu) <- feature_names(features)\n    # create ConservationProblem object\n    conservation_problem(\n      data = list(\n        cost = x,\n        features = features,\n        rij_matrix = rij,\n        feature_abundances_in_total_units = fatu,\n        planning_unit_indices = idx,\n        is_ids_equivalent_to_indices = TRUE\n      )\n    )\n  }\n)"

const rtdal004784Source0004 = `methods::setMethod(
  "problem",
  methods::signature(x = "Spatial", features = "Raster"),
  function(x, features, cost_column, run_checks = TRUE, ...) {
    assert_required(cost_column)
    assert(assertthat::is.string(cost_column))
    problem(
      x,
      suppressWarnings(
        zones(
          features, zone_names = cost_column, feature_names = names(features)
        )
      ),
      cost_column = cost_column,
      run_checks = run_checks,
      ...
    )
})`

const rtdal004784Source0005 = `methods::setMethod(
  "problem",
  methods::signature(x = "Spatial", features = "ZonesRaster"),
  function(x, features, cost_column, run_checks = TRUE, ...) {
    cli_warning(sp_pkg_deprecation_notice)
    cli_warning(raster_pkg_deprecation_notice)
    # assert that arguments are valid
    assert_required(cost_column)
    assert(
      is_inherits(
        x,
        c(
          "SpatialPolygonsDataFrame", "SpatialLinesDataFrame",
          "SpatialPointsDataFrame"
        )
      ),
      nrow(x) > 0,
      is.character(cost_column),
      assertthat::noNA(cost_column),
      all_match_of(cost_column, names(x)),
      length(cost_column) == number_of_zones(features),
      all_columns_inherit(x[, cost_column], "numeric"),
      assertthat::is.flag(run_checks)
    )
    assert_dots_empty()
    # further validation checks
    assert(
      all_columns_any_finite(x[, cost_column]),
      is_same_crs(x, features),
      is_spatial_extents_overlap(x, features)
    )
    verify(all_positive(x[, cost_column]))
    verify(any_nonzero(x[, cost_column]))
    if (run_checks) {
      verify(all_positive(features))
      verify(any_nonzero(features))
      verify(any_nonNA(features))
    }
    # compute rij matrix including non-planning unit cells
    rij <- suppressWarnings(rij_matrix(x, raster::stack(as.list(features))))
    rij <- lapply(seq_len(number_of_zones(features)), function(i) {
      m <- rij[
        ((i - 1) * number_of_features(features)) +
          seq_len(number_of_features(features)), ,
        drop = FALSE]
      rownames(m) <- feature_names(features)
      m
    })
    # calculate feature abundances in total units
    fatu <- vapply(
      rij, Matrix::rowSums, numeric(number_of_features(features)), na.rm = TRUE
    )
    if (!is.matrix(fatu)) {
      fatu <- matrix(
        fatu, nrow = number_of_features(features),
        ncol = number_of_zones(features)
      )
    }
    rownames(fatu) <- feature_names(features)
    colnames(fatu) <- zone_names(features)
    # create rij matrix
    idx <- planning_unit_indices(x, cost_column)
    rij <- lapply(rij, function(x) x[, idx, drop = FALSE])
    names(rij) <- zone_names(features)
    # create ConservationProblem object
    conservation_problem(
      data = list(
        cost = x,
        features = features,
        cost_column = cost_column,
        rij_matrix = rij,
        feature_abundances_in_total_units = fatu,
        planning_unit_indices = idx,
        is_ids_equivalent_to_indices = TRUE
      )
    )
  }
)`

const rtdal004784Source0006 = `methods::setMethod(
  "problem",
  methods::signature(x = "Spatial", features = "character"),
  function(x, features, cost_column, feature_units = NULL, ...) {
    # set defaults
    if (is.null(feature_units)) {
      feature_units <- rep(NA_character_, length(features))
    } else if (assertthat::is.string(feature_units)) {
      feature_units <- rep(feature_units, length(features))
    }
    # assert that arguments are valid
    assert_required(cost_column)
    assert(
      assertthat::is.string(cost_column),
      all_area_units(feature_units, na.rm = TRUE),
      length(feature_units) == length(features)
    )
    # create ConservationProblem object
    problem(
      x,
      zones(features, feature_names = features, zone_names = cost_column),
      cost_column = cost_column,
      feature_units = feature_units,
      ...
    )
  }
)`

const rtdal004784Source0007 = `methods::setMethod(
  "problem",
  methods::signature(x = "Spatial", features = "ZonesCharacter"),
  function(x, features, cost_column, feature_units = NULL, ...) {
    cli_warning(sp_pkg_deprecation_notice)
    # set defaults
    if (is.null(feature_units)) {
      feature_units <- rep(NA_character_, number_of_features(features))
    } else if (assertthat::is.string(feature_units)) {
      feature_units <- rep(feature_units, length(features))
    }
    # assert that arguments are valid
    assert_required(cost_column)
    assert(
      is_inherits(
        x,
        c(
          "SpatialPolygonsDataFrame", "SpatialLinesDataFrame",
          "SpatialPointsDataFrame"
        )
      ),
      inherits(features, "ZonesCharacter"),
      nrow(x) > 0,
      is.character(cost_column),
      assertthat::noNA(cost_column),
      number_of_zones(features) == length(cost_column),
      all_match_of(cost_column, names(x)),
      all_columns_any_finite(x[, cost_column]),
      all_area_units(feature_units, na.rm = TRUE),
      length(feature_units) == number_of_features(features)
    )
    assert_dots_empty()
    assert(
      all_match_of(unlist(as.list(features)), names(x)),
      msg = paste(
        "{.arg features} contains column names that are",
        "not present in {.arg x}"
      )
    )
    assert(
      all_columns_inherit(
        x[, unlist(as.list(features)), drop = FALSE], c("integer", "numeric")
      ),
      msg = c(
        "{.arg features} must refer to {.cls numeric} columns of {.arg x}."
      )
    )
    verify(all_positive(x[, cost_column]))
    verify(any_nonzero(x[, cost_column]))
    verify(all_positive(x[, unlist(features)]))
    verify(any_nonzero(x[, unlist(features)]))
    verify(all_columns_any_finite(x[, unlist(features)]))
    # create rij matrix
    idx <- planning_unit_indices(x, cost_column)
    rij <- lapply(features, function(z) {
      r <- t(as.matrix(x@data[idx, z, drop = FALSE]))
      r[is.na(r)] <- 0
      rownames(r) <- feature_names(features)
      methods::as(r, "sparseMatrix")
    })
    names(rij) <- zone_names(features)
    # calculate feature abundances in total units
    fatu <- colSums(
      x@data[, unlist(as.list(features)), drop = FALSE],
      na.rm = TRUE
    )
    fatu <- matrix(
      fatu,
      ncol = number_of_zones(features),
      nrow = number_of_features(features),
      dimnames = list(feature_names(features), zone_names(features))
    )
    # create ConservationProblem object
    conservation_problem(
      data = list(
        cost = x,
        features = features,
        cost_column = cost_column,
        rij_matrix = rij,
        feature_abundances_in_total_units = fatu,
        planning_unit_indices = idx,
        is_ids_equivalent_to_indices = TRUE,
        feature_units = feature_units
      )
    )
  }
)`

